/* CommerceForge Dev Docs — Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-card: #1c2128;
  --bg-card-hover: #22272e;
  --bg-code: #0d1117;
  --border: rgba(255, 255, 255, 0.08);
  --border-hover: rgba(255, 255, 255, 0.15);
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00e5a0;
  --accent-hover: #00cc8e;
  --accent-cyan: #58d5ff;
  --accent-blue: #475f91;
  --gradient-accent: linear-gradient(135deg, #00e5a0, #58d5ff);
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'SF Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-card: 0 2px 8px rgba(0, 0, 0, 0.3);
  --shadow-hover: 0 4px 16px rgba(0, 0, 0, 0.4);
  --sidebar-width: 260px;
  --topnav-height: 60px;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: var(--accent-cyan); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--accent); }

/* ── Top Navigation ── */
.topnav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  height: var(--topnav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; padding: 0 24px;
}
.topnav-inner {
  width: 100%; max-width: var(--max-width); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
}
.topnav-brand {
  font-weight: 700; font-size: 1.15rem; color: var(--text-primary);
  display: flex; align-items: center; gap: 8px;
}
.topnav-brand svg { width: 24px; height: 24px; }
.topnav-links { display: flex; align-items: center; gap: 28px; }
.topnav-links a {
  color: var(--text-secondary); font-size: 0.9rem; font-weight: 500;
  transition: color 0.2s;
}
.topnav-links a:hover, .topnav-links a.active { color: var(--text-primary); }
.topnav-right { display: flex; align-items: center; gap: 16px; }
.topnav-search {
  display: flex; align-items: center; gap: 6px;
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 6px 12px;
  color: var(--text-muted); font-size: 0.85rem; cursor: pointer;
  transition: border-color 0.2s;
}
.topnav-search:hover { border-color: var(--border-hover); }
.topnav-search kbd {
  background: rgba(255,255,255,0.06); border-radius: 3px;
  padding: 1px 5px; font-size: 0.75rem; font-family: var(--font-mono);
}
.btn-login {
  background: transparent; border: 1px solid var(--border);
  color: var(--text-primary); padding: 6px 16px; border-radius: var(--radius-sm);
  font-size: 0.85rem; font-weight: 500; cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}
.btn-login:hover { border-color: var(--border-hover); background: rgba(255,255,255,0.04); }
.mobile-menu-btn {
  display: none; background: none; border: none; color: var(--text-primary);
  cursor: pointer; padding: 4px;
}

/* ── Layout ── */
.page-wrap { padding-top: var(--topnav-height); }
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.content-with-sidebar {
  display: flex; max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
  gap: 0;
}
.sidebar {
  width: var(--sidebar-width); min-width: var(--sidebar-width);
  border-right: 1px solid var(--border);
  padding: 32px 20px 32px 0;
  position: sticky; top: var(--topnav-height);
  height: calc(100vh - var(--topnav-height));
  overflow-y: auto;
  transition: width 0.3s ease, min-width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
}
.sidebar.collapsed {
  width: 0; min-width: 0; padding: 32px 0;
  opacity: 0; overflow: hidden;
}
.sidebar-toggle {
  display: flex; align-items: center; gap: 6px;
  background: none; border: 1px solid var(--border); color: var(--text-secondary);
  padding: 6px 12px; border-radius: var(--radius-sm);
  font-size: 0.8rem; cursor: pointer; margin-bottom: 20px;
  transition: color 0.2s, border-color 0.2s;
}
.sidebar-toggle:hover { color: var(--text-primary); border-color: var(--border-hover); }
.sidebar-nav { list-style: none; }
.sidebar-nav li { margin-bottom: 4px; }
.sidebar-nav a {
  display: block; padding: 8px 12px; border-radius: var(--radius-sm);
  color: var(--text-secondary); font-size: 0.88rem; font-weight: 500;
  transition: background 0.15s, color 0.15s;
}
.sidebar-nav a:hover { background: rgba(255,255,255,0.04); color: var(--text-primary); }
.sidebar-nav a.active {
  background: rgba(0, 229, 160, 0.08); color: var(--accent);
}
.main-content {
  flex: 1; padding: 32px 0 64px 40px; min-width: 0;
  transition: padding 0.3s ease;
}
.sidebar.collapsed ~ .main-content { padding-left: 0; }

/* ── Hero ── */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}
.hero h1 {
  font-size: 3rem; font-weight: 700; line-height: 1.15;
  margin-bottom: 20px;
  background: var(--gradient-accent);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: 1.15rem; color: var(--text-secondary);
  max-width: 720px; margin: 0 auto 32px; line-height: 1.7;
}
.hero-ctas { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
.btn-primary {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--accent); color: #0d1117; font-weight: 600;
  padding: 12px 24px; border-radius: var(--radius-sm);
  font-size: 0.95rem; border: none; cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}
.btn-primary:hover { background: var(--accent-hover); color: #0d1117; transform: translateY(-1px); }
.btn-secondary {
  display: inline-flex; align-items: center; gap: 6px;
  background: transparent; color: var(--text-primary);
  border: 1px solid var(--border); padding: 12px 24px;
  border-radius: var(--radius-sm); font-size: 0.95rem;
  font-weight: 500; cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}
.btn-secondary:hover { border-color: var(--border-hover); background: rgba(255,255,255,0.03); }

/* ── Section ── */
.section { padding: 64px 0; }
.section-title {
  font-size: 1.75rem; font-weight: 700; margin-bottom: 12px;
}
.section-subtitle {
  color: var(--text-secondary); font-size: 1.05rem; margin-bottom: 40px;
  max-width: 640px; line-height: 1.6;
}

/* ── Product Cards ── */
.cards-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 20px;
}
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: border-color 0.25s, box-shadow 0.25s, transform 0.2s;
  position: relative; overflow: hidden;
}
.card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0;
  height: 3px; background: var(--gradient-accent); opacity: 0;
  transition: opacity 0.25s;
}
.card:hover {
  border-color: var(--border-hover);
  box-shadow: var(--shadow-hover);
  transform: translateY(-2px);
}
.card:hover::before { opacity: 1; }
.card-icon {
  width: 44px; height: 44px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 18px; font-size: 1.3rem;
}
.card-icon.apps { background: rgba(0, 229, 160, 0.12); color: var(--accent); }
.card-icon.storefronts { background: rgba(88, 213, 255, 0.12); color: var(--accent-cyan); }
.card-icon.agents { background: rgba(168, 130, 255, 0.12); color: #a882ff; }
.card h3 { font-size: 1.2rem; font-weight: 600; margin-bottom: 10px; }
.card p { color: var(--text-secondary); font-size: 0.92rem; margin-bottom: 18px; line-height: 1.6; }
.card-link {
  display: inline-flex; align-items: center; gap: 4px;
  color: var(--accent); font-weight: 600; font-size: 0.9rem;
  transition: gap 0.2s;
}
.card-link:hover { gap: 8px; color: var(--accent); }

/* ── CLI Setup Section ── */
.cli-section { padding: 64px 0; }
.cli-header { text-align: center; margin-bottom: 48px; }
.cli-header h2 { font-size: 1.75rem; font-weight: 700; margin-bottom: 12px; }
.cli-header p {
  color: var(--text-secondary); font-size: 1.05rem;
  max-width: 640px; margin: 0 auto; line-height: 1.6;
}
.accordion-group { max-width: 760px; margin: 0 auto; }
.accordion {
  border: 1px solid var(--border); border-radius: var(--radius-md);
  margin-bottom: 12px; overflow: hidden;
  transition: border-color 0.2s;
}
.accordion.active { border-color: rgba(0, 229, 160, 0.3); }
.accordion-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 22px; cursor: pointer; background: var(--bg-card);
  transition: background 0.15s;
}
.accordion-header:hover { background: var(--bg-card-hover); }
.accordion-header h3 { font-size: 1rem; font-weight: 600; display: flex; align-items: center; gap: 10px; }
.accordion-chevron {
  width: 20px; height: 20px; color: var(--text-muted);
  transition: transform 0.3s ease, color 0.2s;
}
.accordion.active .accordion-chevron { transform: rotate(180deg); color: var(--accent); }
.accordion-body {
  max-height: 0; overflow: hidden;
  transition: max-height 0.35s ease;
  background: var(--bg-secondary);
}
.accordion-body-inner { padding: 22px; }
.step-list { list-style: none; counter-reset: step; }
.step-list li {
  counter-increment: step; padding: 10px 0 10px 36px;
  position: relative; color: var(--text-secondary);
  font-size: 0.92rem; line-height: 1.6;
}
.step-list li::before {
  content: counter(step); position: absolute; left: 0; top: 10px;
  width: 24px; height: 24px; border-radius: 50%;
  background: rgba(0, 229, 160, 0.12); color: var(--accent);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem; font-weight: 700;
}

/* ── Package Manager Tabs ── */
.tab-group { margin: 16px 0; }
.tab-bar {
  display: flex; gap: 0; border-bottom: 1px solid var(--border);
  margin-bottom: 0;
}
.tab-btn {
  background: none; border: none; color: var(--text-muted);
  padding: 10px 18px; font-size: 0.85rem; font-weight: 600;
  font-family: var(--font-mono); cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.tab-btn:hover { color: var(--text-secondary); }
.tab-btn.active {
  color: var(--accent); border-bottom-color: var(--accent);
}
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ── Code Block ── */
.code-block {
  background: var(--bg-code); border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 16px 20px;
  font-family: var(--font-mono); font-size: 0.88rem;
  color: var(--text-primary); overflow-x: auto;
  position: relative; line-height: 1.7;
}
.code-block .prompt { color: var(--accent); user-select: none; }
.code-block .command { color: var(--text-primary); }
.code-copy {
  position: absolute; top: 8px; right: 8px;
  background: rgba(255,255,255,0.06); border: 1px solid var(--border);
  border-radius: 4px; padding: 4px 8px; color: var(--text-muted);
  font-size: 0.75rem; cursor: pointer; transition: color 0.2s, background 0.2s;
}
.code-copy:hover { color: var(--text-primary); background: rgba(255,255,255,0.1); }

/* ── Launch CTA ── */
.launch-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 20px;
}
.launch-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 36px;
  display: flex; flex-direction: column;
  transition: border-color 0.25s;
}
.launch-card:hover { border-color: var(--border-hover); }
.launch-card h3 { font-size: 1.2rem; font-weight: 600; margin-bottom: 10px; }
.launch-card p { color: var(--text-secondary); font-size: 0.92rem; margin-bottom: 18px; flex: 1; line-height: 1.6; }

/* ── Community ── */
.community-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}
.community-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 24px;
  display: flex; align-items: center; gap: 14px;
  transition: border-color 0.2s, transform 0.2s;
  cursor: pointer;
}
.community-card:hover {
  border-color: var(--border-hover); transform: translateY(-1px);
}
.community-icon {
  width: 40px; height: 40px; border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  background: rgba(0, 229, 160, 0.08); color: var(--accent);
  font-size: 1.1rem; flex-shrink: 0;
}
.community-card span { font-weight: 500; font-size: 0.95rem; }

/* ── Interior Page Hero ── */
.interior-hero {
  padding: 60px 0 40px;
}
.interior-hero h1 {
  font-size: 2.5rem; font-weight: 700; margin-bottom: 16px;
  background: var(--gradient-accent);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.interior-hero p {
  color: var(--text-secondary); font-size: 1.1rem;
  max-width: 640px; line-height: 1.7;
}

/* ── Surfaces / Building Blocks / Use Cases Grid ── */
.grid-3 {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}
.feature-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 24px;
  transition: border-color 0.2s, transform 0.2s;
}
.feature-card:hover { border-color: var(--border-hover); transform: translateY(-1px); }
.feature-card h4 {
  font-size: 1rem; font-weight: 600; margin-bottom: 8px;
  display: flex; align-items: center; gap: 8px;
}
.feature-card h4 .dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--accent); flex-shrink: 0;
}
.feature-card p { color: var(--text-secondary); font-size: 0.88rem; line-height: 1.6; }

/* ── Best Practices Grid ── */
.bp-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 14px;
}
.bp-item {
  display: flex; align-items: center; gap: 10px;
  padding: 14px 18px; background: var(--bg-card);
  border: 1px solid var(--border); border-radius: var(--radius-md);
  font-size: 0.9rem; font-weight: 500;
  transition: border-color 0.2s;
}
.bp-item:hover { border-color: var(--border-hover); }
.bp-check { color: var(--accent); font-size: 1rem; flex-shrink: 0; }

/* ── Protocol Diagram ── */
.protocol-diagram {
  display: flex; justify-content: center; align-items: center;
  gap: 24px; flex-wrap: wrap; padding: 40px 0;
}
.actor-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 20px 28px;
  text-align: center; min-width: 140px;
  transition: border-color 0.2s;
}
.actor-card:hover { border-color: var(--border-hover); }
.actor-card .actor-label {
  font-weight: 700; font-size: 1rem; margin-bottom: 4px;
}
.actor-card .actor-desc { color: var(--text-secondary); font-size: 0.82rem; }
.actor-arrow {
  color: var(--text-muted); font-size: 1.4rem; flex-shrink: 0;
}

/* ── Support Categories ── */
.support-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
}
.support-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 28px;
  transition: border-color 0.2s;
}
.support-card:hover { border-color: var(--border-hover); }
.support-card h4 { font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.support-card p { color: var(--text-secondary); font-size: 0.88rem; line-height: 1.5; }

/* ── Status Badge ── */
.badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 12px; border-radius: 20px;
  font-size: 0.78rem; font-weight: 600;
}
.badge-soon {
  background: rgba(255, 190, 50, 0.12); color: #ffbe32;
  border: 1px solid rgba(255, 190, 50, 0.2);
}

/* ── Footer ── */
.footer {
  border-top: 1px solid var(--border);
  padding: 48px 0 36px; margin-top: 40px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 32px; margin-bottom: 36px;
}
.footer-col h4 {
  font-size: 0.82rem; font-weight: 600; color: var(--text-muted);
  text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 14px;
}
.footer-col a {
  display: block; color: var(--text-secondary); font-size: 0.88rem;
  padding: 4px 0; transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  border-top: 1px solid var(--border); padding-top: 20px;
  display: flex; justify-content: space-between; align-items: center;
  flex-wrap: wrap; gap: 12px;
}
.footer-bottom span { color: var(--text-muted); font-size: 0.82rem; }

/* ── Responsive ── */
@media (max-width: 900px) {
  .sidebar { display: none; }
  .content-with-sidebar .main-content { padding-left: 0; }
  .hero h1 { font-size: 2.2rem; }
  .interior-hero h1 { font-size: 2rem; }
  .topnav-links { display: none; }
  .mobile-menu-btn { display: block; }
  .topnav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--topnav-height); left: 0; right: 0;
    background: var(--bg-secondary); border-bottom: 1px solid var(--border);
    padding: 16px 24px; gap: 4px;
  }
  .topnav-links.open a { padding: 10px 0; }
  .cards-grid { grid-template-columns: 1fr; }
  .protocol-diagram { flex-direction: column; gap: 12px; }
  .actor-arrow { transform: rotate(90deg); }
}
@media (max-width: 600px) {
  .hero h1 { font-size: 1.8rem; }
  .hero p { font-size: 1rem; }
  .hero-ctas { flex-direction: column; align-items: stretch; }
  .section-title { font-size: 1.4rem; }
  .grid-3 { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: 1fr; }
  .launch-grid { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .bp-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 400px) {
  .bp-grid { grid-template-columns: 1fr; }
}

/* ── Utility ── */
.text-gradient {
  background: var(--gradient-accent);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.mt-0 { margin-top: 0; }
.mb-sm { margin-bottom: 8px; }
.mb-md { margin-bottom: 16px; }
.mb-lg { margin-bottom: 24px; }
.mb-xl { margin-bottom: 36px; }

/* CommerceForge Dev Docs — Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-card: #1c2128;
  --bg-card-hover: #22272e;
  --bg-code: #0d1117;
  --border: rgba(255, 255, 255, 0.08);
  --border-hover: rgba(255, 255, 255, 0.15);
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00e5a0;
  --accent-hover: #00cc8e;
  --accent-cyan: #58d5ff;
  --accent-blue: #475f91;
  --gradient-accent: linear-gradient(135deg, #00e5a0, #58d5ff);
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'SF Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-card: 0 2px 8px rgba(0, 0, 0, 0.3);
  --shadow-hover: 0 4px 16px rgba(0, 0, 0, 0.4);
  --sidebar-width: 260px;
  --topnav-height: 60px;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: var(--accent-cyan); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--accent); }

/* ── Top Navigation ── */
.topnav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  height: var(--topnav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; padding: 0 24px;
}
.topnav-inner {
  width: 100%; max-width: var(--max-width); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
}
.topnav-brand {
  font-weight: 700; font-size: 1.15rem; color: var(--text-primary);
  display: flex; align-items: center; gap: 8px;
}
.topnav-brand svg { width: 24px; height: 24px; }
.topnav-links { display: flex; align-items: center; gap: 28px; }
.topnav-links a {
  color: var(--text-secondary); font-size: 0.9rem; font-weight: 500;
  transition: color 0.2s;
}
.topnav-links a:hover, .topnav-links a.active { color: var(--text-primary); }
.topnav-right { display: flex; align-items: center; gap: 16px; }
.topnav-search {
  display: flex; align-items: center; gap: 6px;
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 6px 12px;
  color: var(--text-muted); font-size: 0.85rem; cursor: pointer;
  transition: border-color 0.2s;
}
.topnav-search:hover { border-color: var(--border-hover); }
.topnav-search kbd {
  background: rgba(255,255,255,0.06); border-radius: 3px;
  padding: 1px 5px; font-size: 0.75rem; font-family: var(--font-mono);
}
.btn-login {
  background: transparent; border: 1px solid var(--border);
  color: var(--text-primary); padding: 6px 16px; border-radius: var(--radius-sm);
  font-size: 0.85rem; font-weight: 500; cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}
.btn-login:hover { border-color: var(--border-hover); background: rgba(255,255,255,0.04); }
.mobile-menu-btn {
  display: none; background: none; border: none; color: var(--text-primary);
  cursor: pointer; padding: 4px;
}

/* ── Layout ── */
.page-wrap { padding-top: var(--topnav-height); }
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.content-with-sidebar {
  display: flex; max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
  gap: 0;
}
.sidebar {
  width: var(--sidebar-width); min-width: var(--sidebar-width);
  border-right: 1px solid var(--border);
  padding: 32px 20px 32px 0;
  position: sticky; top: var(--topnav-height);
  height: calc(100vh - var(--topnav-height));
  overflow-y: auto;
  transition: width 0.3s ease, min-width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
}
.sidebar.collapsed {
  width: 0; min-width: 0; padding: 32px 0;
  opacity: 0; overflow: hidden;
}
.sidebar-toggle {
  display: flex; align-items: center; gap: 6px;
  background: none; border: 1px solid var(--border); color: var(--text-secondary);
  padding: 6px 12px; border-radius: var(--radius-sm);
  font-size: 0.8rem; cursor: pointer; margin-bottom: 20px;
  transition: color 0.2s, border-color 0.2s;
}
.sidebar-toggle:hover { color: var(--text-primary); border-color: var(--border-hover); }
.sidebar-nav { list-style: none; }
.sidebar-nav li { margin-bottom: 4px; }
.sidebar-nav a {
  display: block; padding: 8px 12px; border-radius: var(--radius-sm);
  color: var(--text-secondary); font-size: 0.88rem; font-weight: 500;
  transition: background 0.15s, color 0.15s;
}
.sidebar-nav a:hover { background: rgba(255,255,255,0.04); color: var(--text-primary); }
.sidebar-nav a.active {
  background: rgba(0, 229, 160, 0.08); color: var(--accent);
}
.main-content {
  flex: 1; padding: 32px 0 64px 40px; min-width: 0;
  transition: padding 0.3s ease;
}
.sidebar.collapsed ~ .main-content { padding-left: 0; }

/* ── Hero ── */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}
.hero h1 {
  font-size: 3rem; font-weight: 700; line-height: 1.15;
  margin-bottom: 20px;
  background: var(--gradient-accent);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero p {
  font-size: 1.15rem; color: var(--text-secondary);
  max-width: 720px; margin: 0 auto 32px; line-height: 1.7;
}
.hero-ctas { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
.btn-primary {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--accent); color: #0d1117; font-weight: 600;
  padding: 12px 24px; border-radius: var(--radius-sm);
  font-size: 0.95rem; border: none; cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}
.btn-primary:hover { background: var(--accent-hover); color: #0d1117; transform: translateY(-1px); }
.btn-secondary {
  display: inline-flex; align-items: center; gap: 6px;
  background: transparent; color: var(--text-primary);
  border: 1px solid var(--border); padding: 12px 24px;
  border-radius: var(--radius-sm); font-size: 0.95rem;
  font-weight: 500; cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}
.btn-secondary:hover { border-color: var(--border-hover); background: rgba(255,255,255,0.03); }

/* ── Section ── */
.section { padding: 64px 0; }
.section-title {
  font-size: 1.75rem; font-weight: 700; margin-bottom: 12px;
}
.section-subtitle {
  color: var(--text-secondary); font-size: 1.05rem; margin-bottom: 40px;
  max-width: 640px; line-height: 1.6;
}

/* ── Product Cards ── */
.cards-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 20px;
}
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: border-color 0.25s, box-shadow 0.25s, transform 0.2s;
  position: relative; overflow: hidden;
}
.card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0;
  height: 3px; background: var(--gradient-accent); opacity: 0;
  transition: opacity 0.25s;
}
.card:hover {
  border-color: var(--border-hover);
  box-shadow: var(--shadow-hover);
  transform: translateY(-2px);
}
.card:hover::before { opacity: 1; }
.card-icon {
  width: 44px; height: 44px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 18px; font-size: 1.3rem;
}
.card-icon.apps { background: rgba(0, 229, 160, 0.12); color: var(--accent); }
.card-icon.storefronts { background: rgba(88, 213, 255, 0.12); color: var(--accent-cyan); }
.card-icon.agents { background: rgba(168, 130, 255, 0.12); color: #a882ff; }
.card h3 { font-size: 1.2rem; font-weight: 600; margin-bottom: 10px; }
.card p { color: var(--text-secondary); font-size: 0.92rem; margin-bottom: 18px; line-height: 1.6; }
.card-link {
  display: inline-flex; align-items: center; gap: 4px;
  color: var(--accent); font-weight: 600; font-size: 0.9rem;
  transition: gap 0.2s;
}
.card-link:hover { gap: 8px; color: var(--accent); }

/* ── CLI Setup Section ── */
.cli-section { padding: 64px 0; }
.cli-header { text-align: center; margin-bottom: 48px; }
.cli-header h2 { font-size: 1.75rem; font-weight: 700; margin-bottom: 12px; }
.cli-header p {
  color: var(--text-secondary); font-size: 1.05rem;
  max-width: 640px; margin: 0 auto; line-height: 1.6;
}
.accordion-group { max-width: 760px; margin: 0 auto; }
.accordion {
  border: 1px solid var(--border); border-radius: var(--radius-md);
  margin-bottom: 12px; overflow: hidden;
  transition: border-color 0.2s;
}
.accordion.active { border-color: rgba(0, 229, 160, 0.3); }
.accordion-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 22px; cursor: pointer; background: var(--bg-card);
  transition: background 0.15s;
}
.accordion-header:hover { background: var(--bg-card-hover); }
.accordion-header h3 { font-size: 1rem; font-weight: 600; display: flex; align-items: center; gap: 10px; }
.accordion-chevron {
  width: 20px; height: 20px; color: var(--text-muted);
  transition: transform 0.3s ease, color 0.2s;
}
.accordion.active .accordion-chevron { transform: rotate(180deg); color: var(--accent); }
.accordion-body {
  max-height: 0; overflow: hidden;
  transition: max-height 0.35s ease;
  background: var(--bg-secondary);
}
.accordion-body-inner { padding: 22px; }
.step-list { list-style: none; counter-reset: step; }
.step-list li {
  counter-increment: step; padding: 10px 0 10px 36px;
  position: relative; color: var(--text-secondary);
  font-size: 0.92rem; line-height: 1.6;
}
.step-list li::before {
  content: counter(step); position: absolute; left: 0; top: 10px;
  width: 24px; height: 24px; border-radius: 50%;
  background: rgba(0, 229, 160, 0.12); color: var(--accent);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem; font-weight: 700;
}

/* ── Package Manager Tabs ── */
.tab-group { margin: 16px 0; }
.tab-bar {
  display: flex; gap: 0; border-bottom: 1px solid var(--border);
  margin-bottom: 0;
}
.tab-btn {
  background: none; border: none; color: var(--text-muted);
  padding: 10px 18px; font-size: 0.85rem; font-weight: 600;
  font-family: var(--font-mono); cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.tab-btn:hover { color: var(--text-secondary); }
.tab-btn.active {
  color: var(--accent); border-bottom-color: var(--accent);
}
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ── Code Block ── */
.code-block {
  background: var(--bg-code); border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 16px 20px;
  font-family: var(--font-mono); font-size: 0.88rem;
  color: var(--text-primary); overflow-x: auto;
  position: relative; line-height: 1.7;
}
.code-block .prompt { color: var(--accent); user-select: none; }
.code-block .command { color: var(--text-primary); }
.code-copy {
  position: absolute; top: 8px; right: 8px;
  background: rgba(255,255,255,0.06); border: 1px solid var(--border);
  border-radius: 4px; padding: 4px 8px; color: var(--text-muted);
  font-size: 0.75rem; cursor: pointer; transition: color 0.2s, background 0.2s;
}
.code-copy:hover { color: var(--text-primary); background: rgba(255,255,255,0.1); }

/* ── Launch CTA ── */
.launch-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 20px;
}
.launch-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 36px;
  display: flex; flex-direction: column;
  transition: border-color 0.25s;
}
.launch-card:hover { border-color: var(--border-hover); }
.launch-card h3 { font-size: 1.2rem; font-weight: 600; margin-bottom: 10px; }
.launch-card p { color: var(--text-secondary); font-size: 0.92rem; margin-bottom: 18px; flex: 1; line-height: 1.6; }

/* ── Community ── */
.community-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}
.community-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 24px;
  display: flex; align-items: center; gap: 14px;
  transition: border-color 0.2s, transform 0.2s;
  cursor: pointer;
}
.community-card:hover {
  border-color: var(--border-hover); transform: translateY(-1px);
}
.community-icon {
  width: 40px; height: 40px; border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  background: rgba(0, 229, 160, 0.08); color: var(--accent);
  font-size: 1.1rem; flex-shrink: 0;
}
.community-card span { font-weight: 500; font-size: 0.95rem; }

/* ── Interior Page Hero ── */
.interior-hero {
  padding: 60px 0 40px;
}
.interior-hero h1 {
  font-size: 2.5rem; font-weight: 700; margin-bottom: 16px;
  background: var(--gradient-accent);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.interior-hero p {
  color: var(--text-secondary); font-size: 1.1rem;
  max-width: 640px; line-height: 1.7;
}

/* ── Surfaces / Building Blocks / Use Cases Grid ── */
.grid-3 {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}
.feature-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 24px;
  transition: border-color 0.2s, transform 0.2s;
}
.feature-card:hover { border-color: var(--border-hover); transform: translateY(-1px); }
.feature-card h4 {
  font-size: 1rem; font-weight: 600; margin-bottom: 8px;
  display: flex; align-items: center; gap: 8px;
}
.feature-card h4 .dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--accent); flex-shrink: 0;
}
.feature-card p { color: var(--text-secondary); font-size: 0.88rem; line-height: 1.6; }

/* ── Best Practices Grid ── */
.bp-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 14px;
}
.bp-item {
  display: flex; align-items: center; gap: 10px;
  padding: 14px 18px; background: var(--bg-card);
  border: 1px solid var(--border); border-radius: var(--radius-md);
  font-size: 0.9rem; font-weight: 500;
  transition: border-color 0.2s;
}
.bp-item:hover { border-color: var(--border-hover); }
.bp-check { color: var(--accent); font-size: 1rem; flex-shrink: 0; }

/* ── Protocol Diagram ── */
.protocol-diagram {
  display: flex; justify-content: center; align-items: center;
  gap: 24px; flex-wrap: wrap; padding: 40px 0;
}
.actor-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 20px 28px;
  text-align: center; min-width: 140px;
  transition: border-color 0.2s;
}
.actor-card:hover { border-color: var(--border-hover); }
.actor-card .actor-label {
  font-weight: 700; font-size: 1rem; margin-bottom: 4px;
}
.actor-card .actor-desc { color: var(--text-secondary); font-size: 0.82rem; }
.actor-arrow {
  color: var(--text-muted); font-size: 1.4rem; flex-shrink: 0;
}

/* ── Support Categories ── */
.support-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
}
.support-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 28px;
  transition: border-color 0.2s;
}
.support-card:hover { border-color: var(--border-hover); }
.support-card h4 { font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.support-card p { color: var(--text-secondary); font-size: 0.88rem; line-height: 1.5; }

/* ── Status Badge ── */
.badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 12px; border-radius: 20px;
  font-size: 0.78rem; font-weight: 600;
}
.badge-soon {
  background: rgba(255, 190, 50, 0.12); color: #ffbe32;
  border: 1px solid rgba(255, 190, 50, 0.2);
}

/* ── Footer ── */
.footer {
  border-top: 1px solid var(--border);
  padding: 48px 0 36px; margin-top: 40px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 32px; margin-bottom: 36px;
}
.footer-col h4 {
  font-size: 0.82rem; font-weight: 600; color: var(--text-muted);
  text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 14px;
}
.footer-col a {
  display: block; color: var(--text-secondary); font-size: 0.88rem;
  padding: 4px 0; transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  border-top: 1px solid var(--border); padding-top: 20px;
  display: flex; justify-content: space-between; align-items: center;
  flex-wrap: wrap; gap: 12px;
}
.footer-bottom span { color: var(--text-muted); font-size: 0.82rem; }

/* ── Responsive ── */
@media (max-width: 900px) {
  .sidebar { display: none; }
  .content-with-sidebar .main-content { padding-left: 0; }
  .hero h1 { font-size: 2.2rem; }
  .interior-hero h1 { font-size: 2rem; }
  .topnav-links { display: none; }
  .mobile-menu-btn { display: block; }
  .topnav-links.open {
    display: flex; flex-direction: column;
    position: absolute; top: var(--topnav-height); left: 0; right: 0;
    background: var(--bg-secondary); border-bottom: 1px solid var(--border);
    padding: 16px 24px; gap: 4px;
  }
  .topnav-links.open a { padding: 10px 0; }
  .cards-grid { grid-template-columns: 1fr; }
  .protocol-diagram { flex-direction: column; gap: 12px; }
  .actor-arrow { transform: rotate(90deg); }
}
@media (max-width: 600px) {
  .hero h1 { font-size: 1.8rem; }
  .hero p { font-size: 1rem; }
  .hero-ctas { flex-direction: column; align-items: stretch; }
  .section-title { font-size: 1.4rem; }
  .grid-3 { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: 1fr; }
  .launch-grid { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }
  .bp-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 400px) {
  .bp-grid { grid-template-columns: 1fr; }
}

/* ── Utility ── */
.text-gradient {
  background: var(--gradient-accent);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.mt-0 { margin-top: 0; }
.mb-sm { margin-bottom: 8px; }
.mb-md { margin-bottom: 16px; }
.mb-lg { margin-bottom: 24px; }
.mb-xl { margin-bottom: 36px; }

